import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('skin-cysts',
  kf=["**Epidermoid cysts** are the commonest skin cyst: a mobile dermal nodule with a **central punctum**, filled with keratin ('sebaceous cyst' is a misnomer).",
      "**Pilar (trichilemmal) cysts**: about 90% on the scalp, smooth, no punctum, often multiple and inherited.",
      "Most 'infected' cysts are **inflamed** (ruptured keratin), not infected: antibiotics only for spreading cellulitis or systemic features.",
      "Excise electively once inflammation settles (6–8 weeks), removing the whole wall; cosmetic removal is usually not NHS-funded.",
      "Midline dermoids need imaging before surgery; multiple cysts in a child or young adult suggest **Gardner syndrome** (APC)."],
  epi=[{"t": "**Who**", "sub": ["Epidermoid cysts: young and middle-aged adults, more men; face, neck, trunk, scrotum.", "Pilar cysts: middle-aged women, autosomal dominant tendency."]}],
  aet=["Occluded follicular infundibulum; implantation of epidermis after injury; acne.", "Drugs: isotretinoin, ciclosporin, BRAF inhibitors."],
  myths=["**\"It's a blocked sebaceous gland\"**: the cyst is lined by epidermis and contains keratin, not sebum.", "**\"Squeeze it out\"**: squeezing ruptures the wall and causes inflammation and scarring."],
  patho_lead="A cyst is a sac of **epidermis turned inside out**, shedding keratin into its centre.",
  mech=[("Trapped epidermis", "Follicular infundibulum (or implanted epidermis) forms a closed sac in the dermis."),
        ("Keratin build-up", "The lining keeps making keratin, which collects as soft 'cheesy' material; the punctum is the blocked opening.", "v4-epidermoid-cyst.jpg", "Epidermoid cyst with a central punctum (left) and a ruptured cyst spilling keratin into the dermis with inflammation (right)."),
        ("Rupture and inflammation", "Keratin released into the dermis causes a sterile **foreign-body** reaction: red, hot and tender without infection."),
        ("Recurrence", "Any wall left behind regrows, so excision must remove the whole sac.")],
  histo=["Epidermoid: stratified squamous lining with a granular layer and laminated keratin. Pilar: no granular layer, compact keratin (trichilemmal keratinisation)."],
  special=[{"t": "**Gardner syndrome**", "sub": ["Multiple epidermoid cysts before puberty, osteomas, dental anomalies, desmoids and colorectal polyposis: refer to genetics or colorectal services."]}],
  comp=["Inflammation, rupture and abscess; scarring.", "Recurrence after incomplete excision.", "Malignant change is very rare; a rapidly growing scalp 'cyst' in an older person needs biopsy (proliferating trichilemmal tumour)."],
  prog=["Benign; persists unless excised."],
  see_also=["milia", "lipoma", "other-skin-lumps", "boils-carbuncles", "hidradenitis-suppurativa"])

E('milia',
  kf=["**Milia** are 1–2 mm white **keratin cysts** just under the epidermis.",
      "**Primary**: very common in newborns (nose, cheeks) and on adult eyelids and cheeks.",
      "**Secondary**: after blistering, burns, dermabrasion, or potent topical steroids.",
      "Diagnosis is clinical; look for a cause of secondary milia (e.g. PCT on the backs of the hands).",
      "Reassure; troublesome milia can be de-roofed and expressed; topical retinoids for multiple lesions."],
  epi=[{"t": "**Who**", "sub": ["Up to half of newborns have milia; common at all ages.", "Milia en plaque: rare plaque of milia, usually behind the ear in middle-aged women."]}],
  aet=["Primary: retention of keratin in the lower infundibulum of vellus hairs.", "Secondary: damage to follicles or sweat ducts during blistering or trauma; steroid-induced skin atrophy."],
  myths=["**\"They're whiteheads\"**: milia are closed cysts without an opening; they do not respond to acne cleansers."],
  patho_lead="A milium is a **miniature epidermoid cyst** trapped just under the surface.",
  mech=[("Keratin retention", "Keratin made by a tiny follicle or sweat duct cannot escape to the surface."),
        ("Microcyst", "A sac lined by epidermis fills with layered keratin, seen as a pearly white dot.", "v4-milia-section.jpg", "Milia: tiny keratin cysts in the upper dermis just beneath the epidermis, seen as white dome papules."),
        ("Secondary milia", "When blisters or wounds heal, fragments of epithelium are trapped and form new cysts.")],
  histo=["Small cyst with a stratified squamous lining and laminated keratin, like a tiny epidermoid cyst."],
  special=[{"t": "**Newborns**", "sub": ["Often with Epstein pearls in the mouth; reassure, resolves in weeks."]}],
  comp=["Cosmetic concern only; scarring if picked."],
  prog=["Neonatal milia clear; adult and secondary milia may persist."],
  see_also=["skin-cysts", "neonatal-rashes", "porphyria-cutanea-tarda", "epidermolysis-bullosa", "acne-vulgaris"])

E('lipoma',
  kf=["**Lipomas** are benign tumours of mature fat cells: soft, rubbery, mobile, painless lumps.",
      "Commonest soft-tissue tumour; trunk, neck, shoulders and proximal limbs; usually under 5 cm.",
      "Ultrasound if uncertain. **Sarcoma** features: over 5 cm, deep to fascia, growing, painful or recurrent: urgent imaging or referral (NICE suspected cancer).",
      "Reassure; cosmetic removal is usually not NHS-funded.",
      "Multiple painful lipomas: angiolipomas or **Dercum's disease**; multiple lipomas can be familial."],
  epi=[{"t": "**Who**", "sub": ["Adults 40–60; about 1 in 100 people; more with obesity."]}],
  aet=["Unknown; chromosomal rearrangements (12q13–15, HMGA2) in many; familial multiple lipomatosis; trauma possibly."],
  myths=["**\"Lipomas turn into cancer\"**: they almost never do; the concern is a sarcoma mistaken for a lipoma."],
  patho_lead="A lipoma is a **capsule of normal-looking fat cells** growing slowly beneath the skin.",
  mech=[("Clonal fat cells", "Mature adipocytes proliferate as a lobulated mass with a thin fibrous capsule."),
        ("Slow growth", "Growth is slow and then plateaus; the capsule makes it mobile and well defined."),
        ("Variants", "Angiolipoma (vessels, tender), spindle-cell lipoma (back of neck in older men), deep lipomas within muscle.")],
  histo=["Mature adipocytes with a thin capsule; angiolipomas contain small vessels with microthrombi. Atypical lipomatous tumour shows atypical stromal cells (MDM2 amplification)."],
  special=[{"t": "**Sarcoma red flags**", "sub": ["Size over 5 cm, growth, pain, deep location, recurrence after excision: urgent ultrasound or sarcoma pathway."]}],
  comp=["Pressure on nerves; cosmetic concern; recurrence after excision (rare)."],
  prog=["Benign; persists unless excised."],
  see_also=["skin-cysts", "other-skin-lumps", "dermatofibroma", "dermatofibrosarcoma-protuberans"])

E('dermatofibroma',
  kf=["**Dermatofibroma** (benign fibrous histiocytoma) is a common firm dermal papule, usually on the **legs**.",
      "Firm 'button' with a brown rim; the **dimple sign**: it puckers inwards when pinched.",
      "Dermoscopy: central white scar-like patch with a fine peripheral pigment network.",
      "Benign: reassure. Refer if growing, large, atypical or pigmented in an unusual way (exclude melanoma and DFSP).",
      "Excision leaves a scar often worse than the lesion."],
  epi=[{"t": "**Who**", "sub": ["Young to middle-aged adults, more women; lower legs commonest."]}],
  aet=["Possibly a reaction to minor trauma such as an insect bite or ingrown hair; multiple lesions in immunosuppression (HIV, lupus)."],
  myths=["**\"It's a mole\"**: it is a fibrous lesion, which explains its firmness and the dimple sign."],
  patho_lead="A dermatofibroma is a **fibrous reaction** in the dermis that tethers the skin above.",
  mech=[("Injury", "Minor trauma triggers fibroblasts and histiocytes to proliferate in the dermis."),
        ("Fibrosis", "Collagen and cells form a firm nodule that tethers the overlying epidermis.", "v3-df-dimple-sign.jpg", "The dimple sign: pinching pushes the dermatofibroma downwards."),
        ("Epidermal response", "Overlying epidermis thickens and becomes pigmented, causing the brown rim.")],
  histo=["Spindle cells and histiocytes trapping collagen bundles at the periphery ('collagen balls'); overlying acanthosis with basal pigmentation; CD34 negative (unlike DFSP)."],
  special=[{"t": "**DFSP warning**", "sub": ["A slowly enlarging firm plaque over 2–3 cm, especially on the trunk, may be dermatofibrosarcoma protuberans: refer."]}],
  comp=["Itch or catching on razors; ulceration (rare)."],
  prog=["Persists indefinitely; may flatten over years."],
  see_also=["dermatofibrosarcoma-protuberans", "melanocytic-naevi", "melanoma", "lipoma"])

E('pyogenic-granuloma',
  kf=["**Pyogenic granuloma** (lobular capillary haemangioma) is a fast-growing, **bleeding**, red, moist papule: neither pyogenic nor a granuloma.",
      "Grows over weeks, often after minor trauma; fingers, lips, face, gums (pregnancy epulis).",
      "Triggers: pregnancy, isotretinoin, EGFR inhibitors, other drugs.",
      "Curettage and cautery with **histology** is the usual treatment; send all removed tissue.",
      "Amelanotic melanoma can look identical: a bleeding nodule in an adult needs histology."],
  epi=[{"t": "**Who**", "sub": ["Children and young adults; pregnant women (gingiva)."]}],
  aet=["Minor injury, hormones (pregnancy), drugs (retinoids, EGFR inhibitors, protease inhibitors)."],
  myths=["**\"It's an infection\"**: it is a benign vascular proliferation; antibiotics do not help."],
  patho_lead="Pyogenic granuloma is an **exuberant capillary overgrowth** at a site of injury.",
  mech=[("Trigger", "Minor injury or hormones release angiogenic factors (VEGF)."),
        ("Lobular capillary proliferation", "Capillaries proliferate in lobules, forming a red, friable nodule that bleeds easily.", "v3-pyogenic-granuloma-section.jpg", "Pyogenic granuloma: lobules of capillaries with a collarette of epidermis."),
        ("Collarette", "Epidermis grows around the base forming a collar; the surface often ulcerates.")],
  histo=["Lobular capillary proliferation in an oedematous stroma with an epidermal collarette; ulceration common."],
  special=[{"t": "**Pregnancy**", "sub": ["Gingival lesions often regress after delivery; treat if bleeding or troublesome."]}],
  comp=["Recurrent bleeding; recurrence after treatment (satellite lesions)."],
  prog=["Rarely resolves untreated; treatment is usually curative."],
  see_also=["melanoma", "ingrowing-toenail", "retinoids", "squamous-cell-carcinoma"])

E('paronychia',
  kf=["**Paronychia** is inflammation of the nail fold: **acute** (usually bacterial, hours–days) or **chronic** (over about 6 weeks).",
      "Acute: *S. aureus* or streptococci after minor trauma; one digit; pain, redness, pus.",
      "Chronic: **wet work** destroys the cuticle; irritant dermatitis of the fold with *Candida* colonisation; several fingers.",
      "Acute: warm soaks, drain pus; antibiotics only if spreading, unwell or high risk. Chronic: keep hands dry, cotton-lined gloves, potent steroid to the fold ± azole.",
      "Grouped vesicles: **herpetic whitlow**, do not incise. A single persistent 'paronychia' may be melanoma or SCC."],
  epi=[{"t": "**Who**", "sub": ["Acute: any age, nail-biters, manicures, children sucking fingers.", "Chronic: wet-work occupations (hairdressers, cleaners, caterers, healthcare), diabetes."]}],
  aet=["Breach of the cuticle seal between fold and nail plate."],
  myths=["**\"Chronic paronychia is a fungal infection\"**: it is mainly irritant dermatitis of the fold; *Candida* is secondary."],
  patho_lead="The **cuticle** is the seal; once it is lost, irritants and microbes get under the fold.",
  mech=[("Cuticle loss", "Trauma, picking, manicures or wet work break the cuticle seal."),
        ("Acute infection", "Bacteria enter the fold, forming pus beneath the eponychium.", "v3-paronychia-acute-chronic.jpg", "Acute (single tense red fold with pus) versus chronic paronychia (several swollen folds with lost cuticles)."),
        ("Chronic dermatitis", "Repeated wetting causes irritant dermatitis; the fold lifts from the plate and *Candida* and Gram-negative bacteria colonise the gap."),
        ("Nail plate changes", "Matrix inflammation causes transverse ridges, discolouration and onycholysis."),
        ("Restoring the barrier", "Dry hands and cotton under rubber gloves let the cuticle regrow.", "v3-cotton-under-rubber-gloves.jpg", "Cotton gloves under waterproof gloves protect the nail folds.")],
  special=[{"t": "**Diabetes or immunosuppression**", "sub": ["Lower threshold for antibiotics and review."]}],
  comp=["Abscess, felon, flexor tenosynovitis, osteomyelitis.", "Nail dystrophy; chronic disease lasting months."],
  prog=["Acute: settles in days with drainage. Chronic: months, and recurs unless wet work is controlled."],
  see_also=["ingrowing-toenail", "onychomycosis", "hand-eczema", "nail-signs", "herpes-simplex-labialis"])

E('ingrowing-toenail',
  kf=["**Ingrowing toenail** (onychocryptosis): the nail edge pierces the lateral fold, usually of the **big toe**.",
      "Commonest in teenagers and young men; causes: cutting nails curved or too short, tight shoes, hyperhidrosis, involuted nails.",
      "Stages: inflammation → infection with granulation tissue → chronic fold hypertrophy.",
      "Cut straight across, wide shoes, soaks, lift the edge; antibiotics only for spreading cellulitis.",
      "Recurrent: **partial nail avulsion with phenol** by podiatry (about 95% success). Diabetes or PAD: refer early."],
  epi=[{"t": "**Who**", "sub": ["Adolescents and young adults, males more than females; also older people with thickened nails."]}],
  aet=["Nail cutting, footwear, sweaty feet, trauma, pincer nails.", "Drugs: isotretinoin and EGFR inhibitors cause similar periungual granulation."],
  myths=["**\"Cut a V in the middle of the nail\"**: this does not work; cut straight across.", "**\"Antibiotics fix it\"**: they do not remove the spike of nail."],
  patho_lead="A **spike of nail** acts as a foreign body in the nail fold.",
  mech=[("Penetration", "A sharp nail edge pierces the lateral fold, often after cutting the corner short."),
        ("Inflammation", "The fold becomes red, swollen and painful; bacteria colonise the wound."),
        ("Granulation tissue", "Continued irritation produces moist, bleeding 'proud flesh' overhanging the nail.", "v4-ingrowing-toenail.jpg", "Ingrowing toenail with granulation tissue on the lateral fold; inset: nail cut straight across."),
        ("Cure", "Removing the edge and destroying that strip of matrix (phenol) stops regrowth.")],
  special=[{"t": "**Diabetes and peripheral arterial disease**", "sub": ["High risk of infection, ulceration and amputation: early podiatry."]}],
  comp=["Paronychia, cellulitis, osteomyelitis (rare).", "Recurrence after simple avulsion."],
  prog=["Mild cases settle with conservative care; phenol matricectomy rarely recurs."],
  see_also=["paronychia", "pyogenic-granuloma", "onychomycosis", "nail-signs"])

E('intertrigo',
  kf=["**Intertrigo** is inflammation of skin folds from friction, heat and moisture; it is a pattern, not one disease.",
      "Breasts, groin, axillae, abdominal folds, between toes; obesity, diabetes, incontinence and hot weather predispose.",
      "Look for secondary *Candida* (satellite papules), dermatophyte (active edge), **erythrasma** (coral-red Wood's light) or streptococcus.",
      "Keep folds dry, reduce friction, barrier paste; hydrocortisone 1% for 1–2 weeks; topical azole if candida likely.",
      "Persistent flexural rashes: think inverse psoriasis, seborrhoeic dermatitis, contact allergy, Hailey–Hailey or extramammary Paget's."],
  epi=[{"t": "**Who**", "sub": ["Any age; common in obesity, diabetes, immobility, incontinence and infants (napkin and neck folds)."]}],
  aet=["Skin-on-skin friction, trapped sweat, maceration, and alkaline irritants (urine, faeces)."],
  myths=["**\"Talc keeps folds dry\"**: it can clump and irritate; dry gently and use a barrier."],
  patho_lead="Folds trap heat and moisture, so the barrier **macerates** and rubs raw.",
  mech=[("Occlusion", "Skin-to-skin contact traps sweat and raises temperature.", "v3-intertrigo-fold-section.jpg", "Inside a skin fold: trapped moisture and friction break down the barrier."),
        ("Maceration and friction", "Wet stratum corneum softens and erodes with movement."),
        ("Secondary infection", "Damaged skin is colonised by *Candida*, dermatophytes, *Corynebacterium* (erythrasma) or streptococci."),
        ("Typical sites", "Submammary, axillary, inguinal, abdominal and interdigital folds.", "v3-intertrigo-fold-map.jpg", "Common intertrigo sites.")],
  special=[{"t": "**Skin of colour**", "sub": ["Erythema may look brown or purple; post-inflammatory pigmentation is common."]}],
  comp=["Secondary infection, fissuring, odour, pain; cellulitis in diabetes."],
  prog=["Recurs unless predisposing factors are managed."],
  see_also=["candida-intertrigo", "tinea", "psoriasis", "napkin-dermatitis", "perineal-dermatoses"])
